import json
import os
import socket
from pathlib import Path

import httpx
import httpx2
from starlette.testclient import TestClient

LEDGER_PATH = Path(os.environ["CERES_V3_PROBE_LEDGER"])
ledger = {
    "kind": "controlled-observer-only",
    "seam": "public Starlette TestClient.send",
    "external_network_policy": "deny all socket connects and all non-testserver HTTP sends",
    "testclient_requests": [],
    "turn_requests": [],
    "blocked_http": [],
    "blocked_sockets": [],`n    "allowed_loopback_sockets": [],
}

original_testclient_send = TestClient.send
product_sku = "demo:cn-coke-zero-500ml-bottle"


def sse_response(request, text):
    return httpx2.Response(
        status_code=200,
        headers={"content-type": "text/event-stream; charset=utf-8"},
        content=text.encode("utf-8"),
        request=request,
    )


def frame(event, payload):
    return "event: " + event + "\ndata: " + json.dumps(payload, ensure_ascii=False) + "\n\n"


def public_testclient_send(self, request, *args, **kwargs):
    host = request.url.host
    path = request.url.path
    if host != "testserver":
        ledger["blocked_http"].append({"client": "Starlette TestClient", "method": request.method,
                                        "url": str(request.url)})
        raise httpx2.ConnectError("controlled observer probe blocks outbound HTTP", request=request)
    ledger["testclient_requests"].append({"method": request.method, "path": path})
    if path.startswith("/api/v1/chat/openings/") and path.endswith("/turns/stream"):
        body = json.loads(request.content.decode("utf-8"))
        opening_id = path.split("/")[5]
        index = sum(1 for row in ledger["turn_requests"] if row["opening_id"] == opening_id)
        request_row = {"opening_id": opening_id, "index": index,
                       "request_id": body.get("request_id"), "message": body.get("message")}
        ledger["turn_requests"].append(request_row)
        if index == 0:
            detail_response = self.get("/api/v1/products/" + product_sku)
            detail = detail_response.json()
            if detail_response.status_code != 200 or detail["sku_id"] != product_sku:
                raise AssertionError("seeded zero-sugar product detail was unavailable: " + detail_response.text)
            card = {
                "sku_id": detail["sku_id"],
                "name": detail["name_zh"] or detail["name"],
                "brand": detail["brand"],
                "price_fen": detail["price_fen"],
            }
            ledger["seeded_product"] = {
                "http_status": detail_response.status_code,
                "sku_id": detail["sku_id"],
                "name": card["name"],
                "price_fen": detail["price_fen"],
            }
            valid = frame("service.route", {"status": "completed", "decision": "stay_current"})
            valid += frame("turn.completed", {"answer_status": "completed", "plan": None,
                                                "committed": False, "product_cards": [card]})
            request_row["response_kind"] = "minimal-valid-readonly-turn-with-seeded-card"
            return sse_response(request, valid)
        malformed = frame("service.route", {"status": "completed", "decision": "stay_current"})
        malformed += "event: turn.completed\ndata: {malformed-json\n\n"
        request_row["response_kind"] = "http-200-malformed-selection-sse"
        request_row["response_body"] = malformed
        return sse_response(request, malformed)
    return original_testclient_send(self, request, *args, **kwargs)


TestClient.send = public_testclient_send


for client_type in {httpx.Client, httpx2.Client}:
    original_send = client_type.send

    def blocked_send(self, request, *args, __original=original_send, **kwargs):
        if request.url.host == "testserver":
            return __original(self, request, *args, **kwargs)
        ledger["blocked_http"].append({"client": type(self).__module__ + "." + type(self).__name__,
                                        "method": request.method, "url": str(request.url)})
        raise httpx2.ConnectError("controlled observer probe blocks outbound HTTP", request=request)

    client_type.send = blocked_send


original_socket_connect = socket.socket.connect
original_socket_connect_ex = socket.socket.connect_ex


