    if not isinstance(address, tuple) or not address:
        return False
    try:
        return ipaddress.ip_address(address[0]).is_loopback
    except ValueError:
        return False


def blocked_socket_connect(self, address):
    if is_loopback(address):
        ledger["allowed_loopback_sockets"].append({"operation": "connect", "address": repr(address),
                                                   "reason": "Windows asyncio socketpair for in-process TestClient"})
        return original_socket_connect(self, address)
    ledger["blocked_sockets"].append({"operation": "connect", "address": repr(address)})
    raise OSError("controlled observer probe blocks non-loopback socket connects")


def blocked_socket_connect_ex(self, address):
    if is_loopback(address):
        ledger["allowed_loopback_sockets"].append({"operation": "connect_ex", "address": repr(address),
                                                   "reason": "Windows asyncio socketpair for in-process TestClient"})
        return original_socket_connect_ex(self, address)
    ledger["blocked_sockets"].append({"operation": "connect_ex", "address": repr(address)})
    raise OSError("controlled observer probe blocks non-loopback socket connects")


socket.socket.connect = blocked_socket_connect
socket.socket.connect_ex = blocked_socket_connect_ex


def pytest_sessionfinish(session, exitstatus):
    LEDGER_PATH.parent.mkdir(parents=True, exist_ok=True)
    ledger["pytest_exitstatus"] = exitstatus
    LEDGER_PATH.write_text(json.dumps(ledger, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
